const item = $input.first().json.body || $input.first().json;

const visitorName = item.visitorName || 'Unregistered Guest';
const visitorPhone = item.visitorPhone || 'N/A';
const visitorType = item.visitorType || 'GUEST'; // GUEST, CAB, DELIVERY, CONTRACTOR, SERVICE_TECHNICIAN, HOME_MAINTENANCE
const flatNumber = item.flatNumber || 'A-402';
const tower = item.tower || 'Tower A';
const passCode = item.passCode || 'NONE';
const vehicleNumber = item.vehicleNumber || 'NONE';
const entryTime = item.entryTime || new Date().toISOString();
const expectedDurationMinutes = item.expectedDurationMinutes || (visitorType === 'DELIVERY' ? 20 : visitorType === 'CAB' ? 15 : 180);
const actualStayMinutes = item.actualStayMinutes ?? 0;
const purpose = item.purpose || 'Visit';
const isPreApproved = item.isPreApproved ?? (passCode !== 'NONE');
const gateName = item.gateName || 'Main Gate 1';

const prompt = `You are the Chief Gatekeeper and Visitor Security Auditor for Mana Community Society.
Evaluate the following visitor entry or active stay telemetry against security bylaws and overstay anomaly rules.

Visitor Information:
- Name: ${visitorName}
- Phone: ${visitorPhone}
- Type: ${visitorType}
- Destination: ${tower}, Flat ${flatNumber}
- Pass Code: ${passCode} (Pre-Approved: ${isPreApproved})
- Vehicle: ${vehicleNumber}
- Entry Time: ${entryTime} via ${gateName}
- Expected Duration: ${expectedDurationMinutes} mins
- Current Stay Duration: ${actualStayMinutes} mins
- Stated Purpose: ${purpose}

Security Audit Objectives:
1. Classify Clearance Status (APPROVED, CONDITIONAL_ENTRY, DENIED, OVERSTAY_ALARM).
2. Calculate Risk Score (0 = Completely Safe, 100 = Severe Security Hazard).
3. Detect specific risk triggers (e.g. food/courier delivery lingering >40 mins inside residential tower, unauthorized late-night contractor entry, vehicle discrepancy).
4. Define Gate Guard Action Directive (e.g. allow boom barrier lift, collect physical ID, escort to flat, call resident for verbal re-approval, dispatch patrol to locate overstayed vehicle).
5. Draft instant 1-sentence WhatsApp notification for the hosting flat resident.

Respond ONLY with a valid JSON object matching this schema:
{
  "clearanceStatus": "APPROVED" | "CONDITIONAL_ENTRY" | "DENIED" | "OVERSTAY_ALARM",
  "riskScore": number,
  "isOverstay": boolean,
  "overstaySeverity": "NONE" | "MILD" | "MODERATE" | "CRITICAL",
  "riskFactors": ["Reason 1", "Reason 2"],
  "guardDirective": "Precise operational instruction for duty guard at the gate",
  "residentNotification": "Draft WhatsApp alert for resident",
  "autoCheckoutSuggested": boolean
}`;

return [{
  json: {
    visitorName,
    flatNumber,
    visitorType,
    actualStayMinutes,
    prompt
  }
}];

const geminiResponse = $input.first().json;
const meta = $('Prepare Visitor Audit Prompt').first().json;
let parsed = {};

try {
  const rawText = geminiResponse.candidates[0].content.parts[0].text;
  parsed = JSON.parse(rawText);
} catch (err) {
  const isOver = (meta.actualStayMinutes > 60 && meta.visitorType === 'DELIVERY');
  parsed = {
    clearanceStatus: isOver ? "OVERSTAY_ALARM" : "APPROVED",
    riskScore: isOver ? 75 : 10,
    isOverstay: isOver,
    overstaySeverity: isOver ? "MODERATE" : "NONE",
    riskFactors: isOver ? ["Delivery personnel active duration exceeds standard society delivery window"] : ["Standard visitor entry verified"],
    guardDirective: isOver ? "Contact flat resident to confirm parcel delivery completion and locate vehicle." : "Verify entry pass code and permit entry.",
    residentNotification: `Visitor ${meta.visitorName} checked in for ${meta.flatNumber}. Contact security if unexpected.`,
    autoCheckoutSuggested: false
  };
}

return [{
  json: {
    status: "success",
    auditedAt: new Date().toISOString(),
    visitorSummary: {
      visitorName: meta.visitorName,
      flatNumber: meta.flatNumber,
      visitorType: meta.visitorType
    },
    auditResult: parsed
  }
}];
